const titles={overview:['Enterprise command center','A live operating picture across stores, product, supply chain and enterprise delivery.'],stores:['Store network','Regional performance, store health and opening pipeline.'],analytics:['Performance & insights','Sales, availability, margin, service and operating signals.'],'product-pipeline':['Product introduction lifecycle','Move an idea from supplier discovery through approval, launch and lifecycle review.'],catalog:['Product & SKU catalog','Manage item identity, category, supplier, price, margin and lifecycle.'],assortment:['Assortment planning','Shape store-level range, distribution and launch allocation.'],promotions:['Promotions & pricing','Plan price events, funding, margin guardrails and execution.'],suppliers:['Supplier network','Manage supplier onboarding, scorecards, compliance and performance.'],procurement:['Procurement workbench','Translate demand signals into buying decisions and purchase orders.'],'purchase-orders':['Purchase orders','Track supplier confirmation, delivery commitments and exceptions.'],distribution:['Distribution network','Monitor DC capacity, throughput, inbound and outbound execution.'],receiving:['Receiving & inspection','Verify deliveries, capture variances and release inventory.'],inventory:['Inventory control tower','Monitor availability, replenishment, stock health and inventory accuracy.'],transfers:['Store transfers','Rebalance inventory across the store network.'],'store-ops':['Store operating rhythm','Opening, daily execution, food safety, service and closing controls.'],workforce:['People & workforce','Coverage, schedules, training, hiring and labor readiness.'],quality:['Quality & compliance','Food safety, supplier assurance, audits, traceability and corrective actions.'],customer:['Customer & community','Service recovery, customer signals, local events and loyalty experience.'],expansion:['Expansion command center','Govern the 12-stage store development lifecycle from market thesis to hypercare.'],finance:['Finance & investment','Capital allocation, store economics, operating performance and forecast.'],'it-portfolio':['IT portfolio delivery','Connect strategic outcomes to programs, projects, releases and value realization.'],risks:['RAID & decisions','Resolve cross-functional risks, assumptions, issues, dependencies and decisions.'],reports:['Enterprise reporting','Leadership-ready views across retail operations and transformation.'],admin:['Platform administration','Reference data, roles, operating rules and demo controls.'],shop:['Shop the market','Discover everyday essentials and explore the customer journey.'],'my-orders':['My orders & account','Review purchases, loyalty activity and service requests.']};
const vis=()=>groups.flatMap(g=>g[1]).filter(x=>x[3].includes(S.role)||(S.role==='System Administrator'&&!['shop','my-orders'].includes(x[0]))||(S.role==='Customer'&&['shop','my-orders'].includes(x[0])));
const status=s=>'<span class="status '+(/risk|critical|overdue|red|out of stock|at risk|escalated/i.test(s)?'risk':/watch|amber|low|review|mitigat|progress|arriving/i.test(s)?'warn':/green|on track|approved|received|active|complete|healthy/i.test(s)?'':'info')+'"><i class="dot"></i>'+s+'</span>';
const kpi=(a,b,c,k='')=>'<div class="kpi"><div class="kpi-label">'+a+'</div><div class="kpi-value">'+b+'</div><div class="kpi-foot '+k+'">'+c+'</div></div>';
const btn=(t,a,c='')=>'<button class="btn '+c+'" data-action="'+a+'">'+t+'</button>';
const table=(h,rs)=>'<div class="table-wrap"><table><thead><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rs.join('')+'</tbody></table></div>';
const card=(t,b,s='',act='')=>'<section class="card"><div class="card-head"><div><div class="card-title">'+t+'</div>'+(s?'<div class="card-sub">'+s+'</div>':'')+'</div>'+(act||'')+'</div>'+b+'</section>';
const pageHead=()=>{let t=titles[S.page]||['Operations','Manage connected retail operations.'];return '<div class="page-head"><div><div class="eyebrow">UOWE · MARKETOPS 360 / '+S.role.toUpperCase()+'</div><h1>'+t[0]+'</h1><p>'+t[1]+'</p></div><div class="head-actions"><button class="btn" data-action="help">? Demo guide</button>'+btn('＋ Create action','new-task','primary')+'</div></div>'};
const chart=(v,l)=>'<div class="bar-chart">'+v.map((x,i)=>'<div class="bar-col"><div class="bar '+(i===v.length-1?'hot':'')+'" style="height:'+x+'%"><span>'+x+'</span></div>'+l[i]+'</div>').join('')+'</div>';
function connectedJourney(icon,title,sub,steps,action){
return '<div class="journey"><div class="journey-head"><div class="journey-icon">'+icon+'</div><div><strong>'+title+'</strong><p>'+sub+'</p></div></div><div class="journey-steps">'+steps.map((s,i)=>'<div class="journey-step '+(i<steps.length-1?'done':'current')+'"><span>'+s[0]+'</span><div><b>'+s[1]+'</b><small>'+s[2]+'</small></div></div>').join('')+'</div>'+btn(action[0],action[1],action[2]||'')+'</div>';
}
function dashboard(){
let sales=S.stores.reduce((a,x)=>a+x.sales,0),low=S.products.filter(p=>p.stock<p.par*.6).length;
let inbound=S.shipments.filter(x=>x.status!=='Received').length;
let openRisks=S.risks.filter(x=>x.status!=='Closed').length;
let nextProduct=S.pipeline[0], nextExpansion=S.expansions[0];
return '<div class="hero"><div><div class="hero-tag">Connected operating model · live demo state</div><h2>Run the network.<br>Grow with confidence.</h2><p>One command view connecting customers, stores, merchandising, suppliers, distribution, inventory, expansion and enterprise delivery. Every action creates a visible downstream consequence.</p>'+btn('Open expansion command','go-expansion','lime')+' '+btn('Review critical risks','go-risks')+'</div><div class="hero-art">🏬　🚚<br>🛒　📦</div></div>'+
'<div class="grid kpis">'+kpi('Network sales · MTD',money(sales),'+8.4% vs prior period')+kpi('On-shelf availability','96.8%','+1.2 pts week over week')+kpi('Inbound shipments',inbound,'Receiving actions pending','warn')+kpi('Open enterprise risks',openRisks,'Leadership attention required','bad')+'</div>'+
'<div class="grid two"><div class="card"><div class="card-head"><div><div class="card-title">Cross-functional journeys</div><div class="card-sub">Follow the business event from trigger to outcome.</div></div><span class="status">Shared state</span></div>'+
connectedJourney('🛒','Customer order → store fulfillment','Customer checkout reduces shared inventory and creates an order for store operations.',[['1','Basket','Customer selects items'],['2','Checkout','Order confirmed'],['3','Inventory','On-hand quantity reduced'],['4','Fulfillment','Store prepares pickup']],['Open customer storefront','go-shop'])+
connectedJourney('📦','Low stock → replenishment','Inventory exceptions become a buying signal, then move through PO, inbound and receiving.',[['1','Signal','SKU below par'],['2','Buy','Buyer creates PO'],['3','Inbound','DC receives ASN'],['4','Release','Inventory becomes available']],['Open inventory control','go-inventory'])+
connectedJourney('🏬','New store → go-live','Expansion gates connect facilities, technology, workforce, supply readiness and store operations.',[['1','Develop','Site / permits / build'],['2','Enable','IT + workforce ready'],['3','Supply','Inventory allocated'],['4','Launch','Go-live + hypercare']],['Open expansion command','go-expansion'])+
'</div><div class="card"><div class="card-head"><div><div class="card-title">Today’s decision queue</div><div class="card-sub">The next actions that keep the operating model moving.</div></div>'+btn('Open RAID','go-risks')+'</div>'+
S.tasks.slice(0,5).map(t=>'<div class="list-row"><div class="list-icon">'+(t.priority==='High'?'⚠️':'✓')+'</div><div class="list-main"><strong>'+t.title+'</strong><p>'+t.area+' · '+t.owner+'</p></div>'+status(t.priority+' · '+t.status)+'</div>').join('')+
'<div class="callout" style="margin-top:12px">Decision rule: act at the point of exception, then verify the downstream state. This is the core control-room pattern demonstrated by the prototype.</div></div></div>'+
'<div class="grid three" style="margin-top:14px">'+
card('Product launch control','<div class="eyebrow">'+nextProduct.id+' · GATE '+nextProduct.stage+'/12</div><h3 style="margin:0 0 6px">'+nextProduct.name+'</h3><p class="card-sub">'+nextProduct.supplier+' · Owner '+nextProduct.owner+' · Target '+nextProduct.target+'</p>'+status(nextProduct.risk)+'<div class="progress"><i style="width:'+Math.round(nextProduct.stage/12*100)+'%"></i></div>'+btn('Advance product gate','advance-product'),'Supplier → quality → commercial → SKU → launch')+
card('Store expansion control','<div class="eyebrow">'+nextExpansion.id+' · GATE '+nextExpansion.stage+'/12</div><h3 style="margin:0 0 6px">'+nextExpansion.name+'</h3><p class="card-sub">'+nextExpansion.city+' · Target '+nextExpansion.open+'</p>'+status(nextExpansion.health)+'<div class="progress"><i style="width:'+nextExpansion.completion+'%"></i></div>'+btn('Advance expansion gate','advance-expansion'),'Market thesis → site → build → readiness → hypercare')+
card('Supply chain control','<div class="metric-line"><span>Items below reorder</span><b>'+low+'</b></div><div class="progress"><i style="width:'+Math.max(12,100-low*12)+'%"></i></div><div class="metric-line"><span>Inbound appointments</span><b>'+inbound+'</b></div><div class="progress blue"><i style="width:'+Math.max(20,100-inbound*18)+'%"></i></div>'+btn('Open procurement','go-procurement'),'Inventory → buying → PO → inbound → receiving')+
'</div>'+
'<div class="grid two" style="margin-top:14px">'+card('Store network performance',chart([62,75,69,88,73,92,84],['M','T','W','T','F','S','S']),'Daily sales index · last 7 days')+
card('Operating pulse',S.activities.map(a=>'<div class="list-row"><div class="list-icon">'+a[0]+'</div><div class="list-main"><strong>'+a[1]+'</strong><p>'+a[2]+'</p></div><span class="list-time">'+a[3]+'</span></div>').join(''),'Signals from across the network')+
'</div>'+
'<div class="grid two" style="margin-top:14px">'+card('Store portfolio',table(['Store','Region','Sales MTD','Traffic','Health','Store lead'],S.stores.map(s=>'<tr><td><strong>'+s.name+'</strong><br><small>'+s.id+' · '+s.city+'</small></td><td>'+s.region+'</td><td>'+money(s.sales)+'</td><td>'+s.traffic.toLocaleString()+'</td><td>'+status(s.health)+'</td><td>'+s.manager+'</td></tr>')),'4 locations · 3 operating · 1 in opening pipeline',btn('View stores','go-stores'))+
card('Decisions & attention',S.risks.slice(0,3).map(r=>'<div class="list-row"><div class="list-icon">⚑</div><div class="list-main"><strong>'+r.title+'</strong><p>'+r.area+' · Owner: '+r.owner+'</p></div>'+status(r.severity)+'</div>').join(''),'Cross-functional items requiring action',btn('Open RAID log','go-risks'))+'</div>';
}
function stagesList(names,stage,kind){return '<div class="stage-list">'+names.map((s,i)=>'<div class="stage '+(i<stage-1?'done':i===stage-1?'current':'')+'"><div class="stage-num">'+(i<stage-1?'✓':i+1)+'</div><div><strong>'+s+'</strong><small>'+(i<stage-1?'Gate evidence approved':i===stage-1?'Evidence and sign-off in progress':'Planned milestone')+'</small></div><span class="stage-right">'+(i<stage-1?'Passed':i===stage-1?'Current':'Pending')+'</span></div>').join('')+'</div>'}
function pageStores(){return '<div class="grid kpis">'+kpi('Operating stores',S.stores.filter(s=>s.sales>0).length,'Across '+new Set(S.stores.filter(s=>s.sales>0).map(s=>s.region)).size+' regions')+kpi('Pre-opening',S.stores.filter(s=>s.sales===0).length,'Opening pipeline')+kpi('Network sales',money(S.stores.reduce((a,s)=>a+s.sales,0)),'+8.4% period over period')+kpi('Average store health','94%','Readiness and service index')+'</div>'+card('Store directory',table(['Location','Region','Sales MTD','Customer visits','Health','Store lead','Action'],S.stores.map(s=>'<tr><td><strong>'+s.name+'</strong><br><small>'+s.id+' · '+s.city+'</small></td><td>'+s.region+'</td><td>'+money(s.sales)+'</td><td>'+s.traffic.toLocaleString()+'</td><td>'+status(s.health)+'</td><td>'+s.manager+'</td><td>'+btn('Open','store-detail')+'</td></tr>')),'Store master and regional accountability',btn('＋ Add location','new-expansion','primary'))}
function pageCatalog(){let arr=S.products.filter(p=>(S.search===''||(p.name+p.sku+p.supplier).toLowerCase().includes(S.search.toLowerCase()))&&(S.filter==='All'||p.dept===S.filter));return '<div class="filters"><input class="search" id="search" placeholder="Search SKU, product or supplier…" value="'+escAttr(S.search)+'"><select id="filter"><option>All</option>'+['Produce','Dairy & Alternatives','Pantry','Frozen','Bakery','Snacks','Beverages','Meat & Seafood'].map(x=>'<option '+(S.filter===x?'selected':'')+'>'+x+'</option>').join('')+'</select>'+btn('＋ Create SKU','new-product','primary')+'</div><div class="grid product-grid">'+arr.map(p=>'<div class="product-card"><div class="product-art">'+p.emoji+'</div><div class="product-body"><div class="eyebrow">'+p.sku+' · '+p.dept+'</div><h3>'+p.name+'</h3><p>'+p.supplier+'</p><div class="product-foot"><span>'+money(p.price)+'</span>'+status(p.stock===0?'Out of stock':p.stock<p.par?'Low stock':'Active')+'</div><div class="progress"><i style="width:'+p.margin+'%"></i></div><p>Gross margin '+p.margin+'% · Stock '+p.stock+'</p></div></div>').join('')+'</div>'}
function pagePipeline(){let p=S.pipeline[0];return '<div class="grid kpis">'+kpi('Active introductions',S.pipeline.length,'Across 3 supplier categories')+kpi('Awaiting approval','2','Quality and cost gates','warn')+kpi('Ready to launch','1','Next launch window: Nov 24')+kpi('Lifecycle reviews','4','Due this month')+'</div><div class="grid two">'+card('Product introduction portfolio',table(['Initiative','Supplier','Current stage','Owner','Target launch','Exception','Action'],S.pipeline.map(x=>'<tr><td><strong>'+x.name+'</strong><br><small>'+x.id+'</small></td><td>'+x.supplier+'</td><td>'+x.stage+'/12 · '+S.productStages[x.stage-1]+'</td><td>'+x.owner+'</td><td>'+x.target+'</td><td>'+status(x.risk)+'</td><td>'+btn('Advance gate','advance-product')+'</td></tr>')),'12-gate controlled product lifecycle',btn('＋ New product idea','new-product','primary'))+card('Featured introduction · '+p.name,'<div class="eyebrow">'+p.id+' · GATE '+p.stage+' OF 12</div>'+stagesList(S.productStages,p.stage),'Supplier → quality → commercial → item setup → store launch')+'</div><div class="callout" style="margin-top:14px">A product cannot advance without the evidence required by the current gate. Quality, commercial, item master, supply and store readiness are distinct accountable handoffs.</div>'}
function pageSuppliers(){return '<div class="grid kpis">'+kpi('Approved suppliers',S.suppliers.filter(s=>s.status==='Approved').length,'Across core categories')+kpi('Average score','91.4','Quality, service and delivery')+kpi('Supplier reviews','1','Requires corrective action','warn')+kpi('On-time delivery','96.2%','Rolling 90-day performance')+'</div>'+card('Supplier relationship directory',table(['Supplier','Category','Score','Lead time','Terms','Status','Action'],S.suppliers.map(s=>'<tr><td><strong>'+s.name+'</strong><br><small>'+s.id+'</small></td><td>'+s.category+'</td><td>'+s.score+'/100</td><td>'+s.lead+' days</td><td>'+s.terms+'</td><td>'+status(s.status)+'</td><td>'+btn('Review','supplier-review')+'</td></tr>')),'Supplier master, service scorecards and onboarding',btn('＋ Onboard supplier','new-supplier','primary'))}
function pageProcurement(){let low=S.products.filter(p=>p.stock<p.par);return '<div class="grid kpis">'+kpi('Open purchase orders',S.pos.filter(p=>p.status!=='Received').length,'Supplier commitments')+kpi('Committed spend',money(S.pos.reduce((a,p)=>a+p.amount,0)),'Across active POs')+kpi('Demand alerts',low.length,'Replenishment opportunities','warn')+kpi('Supplier confirmations','94%','Within target window')+'</div><div class="grid two">'+card('Demand & replenishment signals',table(['SKU / Item','Store stock','Par','Suggested buy','Supplier','Priority','Action'],low.map(p=>'<tr><td><strong>'+p.name+'</strong><br><small>'+p.sku+'</small></td><td>'+p.stock+'</td><td>'+p.par+'</td><td>'+Math.max(p.par*2-p.stock,0)+'</td><td>'+p.supplier+'</td><td>'+status(p.stock===0?'Critical':'Replenish')+'</td><td>'+btn('Create PO','create-po')+'</td></tr>')),'Signals combine par levels, sell-through and lead time')+card('Buying controls','<div class="metric-line"><span>Forecast coverage</span><b>18.4 days</b></div><div class="progress"><i style="width:74%"></i></div><div class="metric-line"><span>Open-to-buy utilization</span><b>68%</b></div><div class="progress blue"><i style="width:68%"></i></div><div class="metric-line"><span>Supplier on-time score</span><b>96.2%</b></div><div class="progress green"><i style="width:96%"></i></div><div class="callout">Prioritize stockout risk and high-velocity items, then consolidate supplier orders to reduce receiving and freight friction.</div>','Demand planning and commercial guardrails')+'</div>'+card('Purchase order register',table(['PO','Supplier','Created','Lines','Value','Status','Action'],S.pos.map(p=>'<tr><td><strong>'+p.id+'</strong></td><td>'+p.supplier+'</td><td>'+p.date+'</td><td>'+p.lines+'</td><td>'+money(p.amount)+'</td><td>'+status(p.status)+'</td><td>'+btn('View','po-detail')+'</td></tr>')),'Purchase-to-pay control')}
function pageDistribution(){return '<div class="grid kpis">'+kpi('Distribution centers','2','West and South network')+kpi('Inbound today','340 cases','3 supplier appointments')+kpi('Outbound waves','8','Store replenishment waves')+kpi('Dock utilization','78%','Within operating capacity')+'</div><div class="grid two">'+card('DC West · Operating status','<div class="metric-line"><span>Receiving capacity</span><b>82%</b></div><div class="progress"><i style="width:82%"></i></div><div class="metric-line"><span>Pick / pack completion</span><b>74%</b></div><div class="progress blue"><i style="width:74%"></i></div><div class="metric-line"><span>Outbound dispatch</span><b>6 of 8 waves</b></div><div class="progress green"><i style="width:75%"></i></div><p class="card-sub">Dock 1: Valley Fresh · Dock 2: Golden Grain · Dock 3: open</p>')+card('DC South · Operating status','<div class="metric-line"><span>Receiving capacity</span><b>68%</b></div><div class="progress"><i style="width:68%"></i></div><div class="metric-line"><span>Pick / pack completion</span><b>88%</b></div><div class="progress blue"><i style="width:88%"></i></div><div class="metric-line"><span>Outbound dispatch</span><b>5 of 5 waves</b></div><div class="progress green"><i style="width:100%"></i></div><p class="card-sub">Dock 1: East Harbor · Dock 2: clear · Cold chain stable</p>')+'</div>'+renderers.receiving()}
function pageReceiving(){return card('Inbound receiving queue',table(['ASN','Supplier','PO','Destination','ETA','Cases','Status','Action'],S.shipments.map(s=>'<tr><td><strong>'+s.id+'</strong></td><td>'+s.supplier+'</td><td>'+s.po+'</td><td>'+s.dc+'</td><td>'+s.eta+'</td><td>'+s.cases+'</td><td>'+status(s.status)+'</td><td>'+btn(s.status==='Received'?'Received':'Inspect & receive','receive-shipment')+'</td></tr>')),'Match ASN to PO, count cases, inspect quality and record variances',btn('＋ Record unscheduled delivery','new-receipt','primary'))}
function pageInventory(){return '<div class="grid kpis">'+kpi('Active SKUs',S.products.length,'Across core categories')+kpi('Below par',S.products.filter(p=>p.stock<p.par).length,'Replenishment needed','warn')+kpi('Stockout SKUs',S.products.filter(p=>p.stock===0).length,'Customer availability risk','bad')+kpi('Inventory accuracy','98.1%','Cycle count confidence')+'</div>'+card('Inventory health by item',table(['Item','Department','Supplier','On hand','Par','Coverage','Health','Action'],S.products.map(p=>'<tr><td><strong>'+p.name+'</strong><br><small>'+p.sku+'</small></td><td>'+p.dept+'</td><td>'+p.supplier+'</td><td>'+p.stock+'</td><td>'+p.par+'</td><td><div class="progress" style="width:90px"><i style="width:'+Math.min(100,p.stock/Math.max(1,p.par)*100)+'%"></i></div></td><td>'+status(p.stock===0?'Out of stock':p.stock<p.par?'Replenish':'Healthy')+'</td><td>'+btn('Adjust','adjust-stock:'+p.sku)+'</td></tr>')),'Inventory is shared across store, procurement and customer experiences',btn('＋ Add inventory item','new-product','primary'))+(S.inventoryAdjustments?.length?card('Recent inventory adjustments',table(['SKU','Previous','Verified','Reason','Reference','Role'],S.inventoryAdjustments.map(x=>'<tr><td>'+x.sku+'</td><td>'+x.before+'</td><td>'+x.after+'</td><td>'+x.reason+'</td><td>'+x.reference+'</td><td>'+x.role+'</td></tr>')),'Changes made during this demo session'):'')}
function pageTransfers(){let seed=[['TR-2204','Westside','Downtown','3 SKUs','24','Demand imbalance','Awaiting approval'],['TR-2201','North Park','Westside','2 SKUs','18','Promotion support','In transit'],['TR-2198','Downtown','North Park','1 SKU','12','Near expiry rotation','Completed']].map(r=>'<tr>'+r.map((v,i)=>'<td>'+(i===0?'<strong>'+v+'</strong>':i===6?status(v):v)+'</td>').join('')+'<td>'+btn('Process','transfer-action')+'</td></tr>');let extra=(S.transferLog||[]).map(x=>'<tr><td><strong>'+x.id+'</strong></td><td>'+x.from+'</td><td>'+x.to+'</td><td>'+x.sku+'</td><td>'+x.units+'</td><td>'+x.reason+'</td><td>'+status(x.status)+'</td><td>'+btn('Process','transfer-action')+'</td></tr>');return card('Store-to-store inventory transfers',table(['Transfer','From','To','Items','Units','Reason','Status','Action'],extra.concat(seed)),'Rebalance store stock before incremental supplier orders',btn('＋ Create transfer','new-transfer','primary'))}
function pageAssortment(){return '<div class="grid two">'+card('Assortment by store',table(['Department','Westside','North Park','Downtown','Irvine opening'],[['Produce','142','138','136','148'],['Dairy & alternatives','96','92','94','101'],['Pantry','310','298','304','322'],['Frozen','88','90','86','92'],['Bakery','54','51','53','58']].map(r=>'<tr>'+r.map((v,i)=>'<td>'+(i===0?'<strong>'+v+'</strong>':v)+'</td>').join('')+'</tr>')),'Store-specific range and space allocation')+card('Assortment guardrails',['Core assortment coverage','Local / regional items','New item trial allocation'].map((x,i)=>'<div class="metric-line"><span>'+x+'</span><b>'+[94,12,4.5][i]+'%</b></div><div class="progress"><i style="width:'+[94,12,45][i]+'%"></i></div>').join('')+'<p class="card-sub">Opening assortment includes initial fill, shelf capacity, cold-chain constraints and local demand.</p>')+'</div>'}
function pagePromotions(){return card('Promotion calendar',table(['Campaign','Department','Mechanic','Window','Funding','Margin floor','Status'],[['Winter citrus feature','Produce','Featured placement','Nov 23–29','Supplier co-op','38%','Approved'],['Pantry stock-up','Pantry','Multi-buy','Nov 27–Dec 03','Retail funded','42%','Review'],['Holiday bakery','Bakery','Seasonal feature','Dec 10–24','Shared','45%','Draft']].map(r=>'<tr>'+r.map((v,i)=>'<td>'+(i===0?'<strong>'+v+'</strong>':i===6?status(v):v)+'</td>').join('')+'</tr>')),'Price events, promotional funding and gross-margin guardrails',btn('＋ Plan promotion','new-promotion','primary'))}
function pageWorkforce(){return '<div class="grid kpis">'+kpi('Scheduled crew','153','Across stores and DCs')+kpi('Coverage','93%','Target 95%','warn')+kpi('Open shifts','14','5 high priority','bad')+kpi('Training current','97%','Food safety and service')+'</div><div class="grid two">'+card('Workforce coverage',S.team.map(t=>'<div class="metric-line"><span>'+t.name+' · '+t.count+' people</span><b>'+t.coverage+'%</b></div><div class="progress"><i style="width:'+t.coverage+'%"></i></div><div class="card-sub">'+t.open+' open shifts / positions</div>').join(''))+card('People operations priorities',['Open hiring requisitions','Food safety certification renewals','Irvine opening team recruitment','Peak-period shift coverage'].map((x,i)=>'<div class="list-row"><div class="list-icon">♙</div><div class="list-main"><strong>'+x+'</strong><p>'+['3 roles · Store leadership','8 crew members due this week','Target staffing 42 · 68% filled','West region · Weekend coverage'][i]+'</p></div>'+status(i===2?'At risk':'In progress')+'</div>').join(''))+'</div>'+card('Crew & shift overview',table(['Team','People','Coverage','Open shifts','Training','Action'],S.team.map(t=>'<tr><td><strong>'+t.name+'</strong></td><td>'+t.count+'</td><td>'+t.coverage+'%</td><td>'+t.open+'</td><td>97%</td><td>'+btn('View schedule','workforce-detail')+'</td></tr>')),'Illustrative workforce data',btn('＋ Create shift / role','new-task','primary'))}
function pageStoreOps(){return '<div class="grid kpis">'+kpi('Store opening checks','97%','Across operating stores')+kpi('Daily tasks completed','86%','On pace')+kpi('Customer service','4.7/5','Rolling 30 days')+kpi('Food safety exceptions','1','Corrective action open','warn')+'</div><div class="grid two">'+card('Daily operating checklist',S.tasks.map(t=>'<div class="list-row"><div class="list-icon">✓</div><div class="list-main"><strong>'+t.title+'</strong><p>'+t.area+' · '+t.owner+' · Due '+t.due+'</p></div>'+status(t.status)+'</div>').join(''),'Opening → trading hours → closing controls',btn('＋ Add task','new-task','primary'))+card('Store execution standards',stagesList(['Opening temperature and safety checks','Freshness and date rotation','Shelf availability and presentation','Customer service and issue recovery','Cash office and loss prevention','Closing reconciliation and handover'],4),'Daily control framework')+'</div>'}
function pageQuality(){return '<div class="grid kpis">'+kpi('Audit compliance','98.6%','Above 98% target')+kpi('Open corrective actions','3','1 overdue','warn')+kpi('Supplier quality','95.2%','Rolling score')+kpi('Traceability readiness','100%','Core categories')+'</div><div class="grid two">'+card('Quality & food safety controls',table(['Control','Scope','Last completed','Owner','Result','Action'],[['Cold-chain temperature','DC West / South','Today · 8:30','DC Quality','Pass'],['Fresh produce inspection','Inbound ASN-7302','Pending','Quality lead','Awaiting'],['Store sanitation audit','Westside','Nov 19','Store Captain','Pass'],['Supplier documentation','Valley Fresh Farms','Nov 18','Quality Manager','Pass']].map(r=>'<tr>'+r.map((v,i)=>'<td>'+(i===0?'<strong>'+v+'</strong>':i===4?status(v):v)+'</td>').join('')+'<td>'+btn('Open','quality-detail')+'</td></tr>')),'Audit plan, inspection evidence and release controls')+card('Corrective action register',S.risks.filter(r=>/supplier|quality|food/i.test(r.area)).map(r=>'<div class="list-row"><div class="list-main"><strong>'+r.title+'</strong><p>'+r.owner+' · Due '+r.due+'</p></div>'+status(r.severity)+'</div>').join(''),'Non-conformance and supplier corrective action')+'</div>'}
function pageCustomer(){return '<div class="grid two">'+card('Customer service workbench',table(['Case','Customer','Reason','Channel','Age','Status','Action'],[['CS-1084','J. Morgan','Missing item','In store','2h','Open'],['CS-1081','A. Lee','Product quality','Email','5h','Investigating'],['CS-1074','S. Patel','Loyalty points','Web','1d','Resolved']].map(r=>'<tr>'+r.map((v,i)=>'<td>'+(i===0?'<strong>'+v+'</strong>':i===5?status(v):v)+'</td>').join('')+'<td>'+btn('Open case','customer-case')+'</td></tr>')),'Service recovery and customer feedback',btn('＋ Create case','new-case','primary'))+card('Community & loyalty signals','<div class="kpi-value">12,840</div><p class="card-sub">Market Circle active members</p><div class="metric-line"><span>Repeat visit rate</span><b>64%</b></div><div class="metric-line"><span>Customer satisfaction</span><b>4.7 / 5</b></div><div class="progress green"><i style="width:94%"></i></div><p class="card-sub">Upcoming: local producer tasting · Saturday, 11 AM</p>')+'</div>'}
function pageExpansion(){let x=S.expansions[0];return '<div class="grid kpis">'+kpi('Active expansion projects',S.expansions.length,'3 markets in development')+kpi('Capital portfolio',money(S.expansions.reduce((a,x)=>a+x.budget,0)),'Approved project budgets')+kpi('Forecast variance',money(S.expansions.reduce((a,x)=>a+x.forecast-x.budget,0)),'Portfolio forecast vs budget','warn')+kpi('Next planned opening','Jan 18','Irvine Market')+'</div><div class="grid two">'+card('Expansion portfolio',table(['Project','Stage gate','Budget','Spent','Forecast','Opening','Health','Action'],S.expansions.map(x=>'<tr><td><strong>'+x.name+'</strong><br><small>'+x.id+' · '+x.city+'</small></td><td>'+x.stage+'/12</td><td>'+money(x.budget)+'</td><td>'+money(x.spent)+'</td><td>'+money(x.forecast)+'</td><td>'+x.open+'</td><td>'+status(x.health)+'</td><td>'+btn('Manage','expansion-detail')+'</td></tr>')),'12-stage capital delivery and opening governance',btn('＋ New expansion project','new-expansion','primary'))+card('Featured project · '+x.name,'<div class="eyebrow">STAGE '+x.stage+' OF 12 · '+x.completion+'% COMPLETE</div>'+stagesList(S.stages,x.stage),'Cross-functional stage gates',btn('Advance stage gate','advance-expansion','primary'))+'</div><div class="grid two" style="margin-top:14px">'+card('Capital profile','<div class="metric-line"><span>Approved budget</span><b>'+money(x.budget)+'</b></div><div class="metric-line"><span>Actual spend</span><b>'+money(x.spent)+'</b></div><div class="progress"><i style="width:'+(x.spent/x.budget*100)+'%"></i></div><div class="metric-line"><span>Estimate at completion</span><b>'+money(x.forecast)+'</b></div><div class="metric-line"><span>Forecast variance</span><b>'+money(x.forecast-x.budget)+'</b></div>','Budget · actual · forecast')+card('Opening readiness dimensions',['Site & lease','Permits & inspections','Construction & facilities','Technology & connectivity','Supplier & inventory readiness','Leadership & crew staffing','Customer experience & launch'].map((v,i)=>'<div class="metric-line"><span>'+v+'</span><b>'+[100,88,93,86,82,68,55][i]+'%</b></div><div class="progress"><i style="width:'+[100,88,93,86,82,68,55][i]+'%"></i></div>').join(''),'Evidence-based go-live readiness')+'</div>'}
function pageFinance(){return '<div class="grid kpis">'+kpi('Retail sales · MTD',money(483600),'+8.4% vs plan')+kpi('Gross margin','38.7%','+0.6 pts vs plan')+kpi('Operating expense',money(172400),'Within monthly forecast')+kpi('Expansion capital',money(8600000),'Portfolio authorization')+'</div><div class="grid two">'+card('Sales & margin trend',chart([55,61,64,59,74,82,89],['M','T','W','T','F','S','S']),'Indexed weekly performance')+card('Capital governance','<div class="metric-line"><span>Approved capital</span><b>'+money(8600000)+'</b></div><div class="progress"><i style="width:72%"></i></div><div class="metric-line"><span>Committed / spent</span><b>'+money(6200000)+'</b></div><div class="metric-line"><span>Forecast at completion</span><b>'+money(8700000)+'</b></div><div class="callout">Portfolio forecast is $100K above approved authorization. Pasadena permit and construction assumptions require review.</div>')+'</div>'+card('Store unit economics',table(['Store','Sales MTD','Gross margin','Labor %','Waste %','Contribution'],S.stores.slice(0,3).map(s=>'<tr><td><strong>'+s.name+'</strong></td><td>'+money(s.sales)+'</td><td>38.7%</td><td>17.2%</td><td>1.8%</td><td>'+money(s.sales*.205)+'</td></tr>')),'Illustrative store-level financial view')}
function pageIT(){return '<div class="grid kpis">'+kpi('Strategic initiatives',S.initiatives.length,'Across 4 delivery streams')+kpi('Portfolio progress','64%','Weighted delivery')+kpi('Budget utilization','72%','Within current envelope')+kpi('Red / amber initiatives','2','Leadership intervention','warn')+'</div><div class="grid two">'+card('Strategic delivery portfolio',table(['Initiative','Business owner','Phase','Progress','Spend / budget','Health','Action'],S.initiatives.map(x=>'<tr><td><strong>'+x.name+'</strong><br><small>'+x.id+'</small></td><td>'+x.owner+'</td><td>'+x.phase+'</td><td>'+x.progress+'%<div class="progress" style="width:85px"><i style="width:'+x.progress+'%"></i></div></td><td>'+money(x.spend)+' / '+money(x.budget)+'</td><td>'+status(x.health)+'</td><td>'+btn('Open','initiative-detail')+'</td></tr>')),'Strategy → value streams → initiatives → releases',btn('＋ Create initiative','new-initiative','primary'))+card('Delivery governance cadence',stagesList(['Daily delivery team stand-up','Weekly value stream review','Biweekly release / integration review','Monthly portfolio steering','Store opening readiness gate'],5),'Decision rights and management rhythm')+'</div><div class="grid two" style="margin-top:14px">'+card('Release calendar',table(['Release','Scope','Target','Environment','Readiness'],[['REL-2.8','Inventory visibility','Nov 27','Production','86%'],['REL-3.0','Store opening toolkit','Dec 08','UAT','72%'],['REL-3.1','Customer experience','Dec 19','Build','48%']].map(r=>'<tr>'+r.map((v,i)=>'<td>'+(i===0?'<strong>'+v+'</strong>':i===4?status(v):v)+'</td>').join('')+'</tr>')),'Release management and change windows')+card('Value realization','<div class="metric-line"><span>Store availability improvement</span><b>+2.4 pts</b></div><div class="progress green"><i style="width:80%"></i></div><div class="metric-line"><span>Receiving cycle time</span><b>-18%</b></div><div class="progress"><i style="width:72%"></i></div><div class="metric-line"><span>Manual reconciliation effort</span><b>-26%</b></div><div class="progress blue"><i style="width:86%"></i></div><p class="card-sub">Illustrative targets; benefit baselines and realized outcomes require business validation.</p>')+'</div>'}
function pageRisks(){return '<div class="grid kpis">'+kpi('Open risks & issues',S.risks.length,'Across enterprise initiatives')+kpi('Critical / high',S.risks.filter(r=>/Critical|High/.test(r.severity)).length,'Escalation threshold','bad')+kpi('Open decisions','3','Awaiting accountable owner','warn')+kpi('Dependencies','8','Cross-functional')+'</div>'+card('RAID register',table(['ID','Risk / issue','Area','Owner','Severity','Due','Status','Action'],S.risks.map(r=>'<tr><td><strong>'+r.id+'</strong></td><td>'+r.title+'</td><td>'+r.area+'</td><td>'+r.owner+'</td><td>'+status(r.severity)+'</td><td>'+r.due+'</td><td>'+status(r.status)+'</td><td>'+btn('Resolve','resolve-risk')+'</td></tr>')),'Risks · assumptions · issues · dependencies and decisions',btn('＋ Log RAID item','new-risk','primary'))}
function pageAnalytics(){return '<div class="grid kpis">'+kpi('Sales growth','+8.4%','Period over period')+kpi('On-shelf availability','96.8%','+1.2 pts')+kpi('Waste rate','1.8%','-0.3 pts')+kpi('Customer satisfaction','4.7/5','+0.2')+'</div><div class="grid two">'+card('Sales index by day',chart([52,59,68,64,76,83,91],['M','T','W','T','F','S','S']),'Network sales trend')+card('Availability by department',['Produce','Dairy','Pantry','Frozen','Bakery'].map((x,i)=>'<div class="metric-line"><span>'+x+'</span><b>'+[97,95,98,96,94][i]+'%</b></div><div class="progress green"><i style="width:'+[97,95,98,96,94][i]+'%"></i></div>').join(''),'Shelf availability')+'</div><div class="grid three" style="margin-top:14px">'+card('Customer signals','<div class="kpi-value">4.7/5</div><p class="card-sub">Customer satisfaction</p><div class="metric-line"><span>Repeat visit rate</span><b>64%</b></div>')+card('Supply chain signals','<div class="kpi-value">96.2%</div><p class="card-sub">Supplier on-time delivery</p><div class="metric-line"><span>Receiving accuracy</span><b>98.4%</b></div>')+card('People & quality signals','<div class="kpi-value">93%</div><p class="card-sub">Workforce coverage</p><div class="metric-line"><span>Training compliance</span><b>97%</b></div>')+'</div>'}
function pageReports(){return '<div class="grid three">'+[['Executive operating review','Network sales, margin, availability and enterprise risk','📊'],['Supply chain scorecard','Supplier performance, inbound, DC throughput and store availability','🚚'],['Store performance pack','Sales, labor, waste, customer experience and readiness','🏬'],['Expansion governance pack','Stage gates, capital forecast, opening readiness and RAID','🧭'],['IT portfolio review','Delivery health, releases, dependencies and value realization','💻'],['Quality & compliance pack','Audit results, supplier quality, traceability and corrective actions','✓']].map(x=>card(x[2]+' '+x[0],'<p class="card-sub">'+x[1]+'</p>'+btn('Generate report','report-action','primary'))).join('')+'</div>'}
function pageAdmin(){return '<div class="grid two">'+card('Role-based experiences',roles.map(r=>'<div class="list-row"><div class="list-icon">♙</div><div class="list-main"><strong>'+r+'</strong><p>'+groups.flatMap(g=>g[1]).filter(i=>i[3].includes(r)||r==='System Administrator').length+' accessible work areas</p></div>'+status('Configured')+'</div>').join(''))+card('Operating reference data',stagesList(['Store and region hierarchy','Department and category taxonomy','Supplier master and service levels','Product and SKU lifecycle','Stage-gate evidence requirements','Approval thresholds and escalation rules','Workforce roles and calendars'],7))+'</div><div class="callout" style="margin-top:14px">Role switching demonstrates intended navigation and responsibility boundaries. It is not an authorization or security boundary.</div>'}
function shop(){let arr=S.products.filter(p=>(!S.search||(p.name+p.dept).toLowerCase().includes(S.search.toLowerCase()))&&(S.filter==='All'||p.dept===S.filter));return '<div class="storefront"><div class="store-top"><div class="brand"><div class="brand-mark">U</div><div>UOWE MARKET <small>GOOD FOOD · GOOD NEIGHBORS</small></div></div><div class="store-nav">Departments　 New & seasonal　 Local favorites　 About our market</div><button class="btn dark" data-action="cart">🛒 Basket ('+S.cart.reduce((a,x)=>a+x.qty,0)+')</button></div><div class="hero"><div><div class="hero-tag">A neighborhood market experience</div><h2>Find something<br>good today.</h2><p>Explore thoughtful everyday essentials, seasonal finds and neighborhood favorites. Shop online and choose convenient pickup.</p><button class="btn lime" data-action="browse">Explore departments ↓</button></div><div class="hero-art">🥑　🥬<br>🍞　🍓</div></div><div class="filters"><input class="search" id="search" placeholder="Search products…" value="'+S.search+'"></div><div class="dept-pills">'+['All','Produce','Dairy & Alternatives','Pantry','Frozen','Bakery','Snacks','Beverages','Meat & Seafood'].map(d=>'<button class="dept-pill '+(S.filter===d?'active':'')+'" data-filter="'+d+'">'+d+'</button>').join('')+'</div><div class="grid product-grid">'+arr.map(p=>'<div class="product-card"><div class="product-art">'+p.emoji+'</div><div class="product-body"><div class="eyebrow">'+p.dept+'</div><h3>'+p.name+'</h3><p>Thoughtfully selected for your table.</p><div class="product-foot"><span>'+money(p.price)+'</span><span class="tag">'+(p.stock>0?'In stock':'Limited availability')+'</span></div><button class="btn primary" style="width:100%;margin-top:10px" data-add="'+p.sku+'" '+(p.stock===0?'disabled':'')+'>Add to basket</button></div></div>').join('')+'</div><div class="callout" style="margin-top:14px">Customer checkout creates a shared order and updates the same inventory view used by store, procurement and distribution roles.</div></div><button class="cart-fab" data-action="cart">🛒 Basket · '+S.cart.reduce((a,x)=>a+x.qty,0)+' items</button>'}
function myOrders(){return card('Your orders',S.orders.length?table(['Order','Placed','Items','Total','Fulfillment','Status'],S.orders.map(o=>'<tr><td><strong>'+o.id+'</strong></td><td>'+o.date+'</td><td>'+o.lines+'</td><td>'+money(o.total)+'</td><td>'+o.fulfillment+'</td><td>'+status(o.status)+'</td></tr>')):'<div class="empty">No orders yet. Visit the storefront to place a demo order.</div>','Customer account · '+S.customer.name+' · '+S.customer.loyalty+' · '+S.customer.points+' points',btn('Shop now','go-shop','primary'))}
const renderers={overview:dashboard,stores:pageStores,analytics:pageAnalytics,'product-pipeline':pagePipeline,catalog:pageCatalog,suppliers:pageSuppliers,procurement:pageProcurement,'purchase-orders':pageProcurement,distribution:pageDistribution,receiving:pageReceiving,inventory:pageInventory,transfers:pageTransfers,assortment:pageAssortment,promotions:pagePromotions,workforce:pageWorkforce,'store-ops':pageStoreOps,quality:pageQuality,customer:pageCustomer,expansion:pageExpansion,finance:pageFinance,'it-portfolio':pageIT,risks:pageRisks,reports:pageReports,admin:pageAdmin};
const pageHelp={overview:"This command center connects customer demand, stores, merchandising, supply chain, expansion and IT delivery.","product-pipeline":"Product introduction moves through controlled gates from supplier submission to quality, commercial approval, SKU setup, assortment, PO, launch and lifecycle review.",procurement:"Procurement converts inventory or forecast signals into buying decisions, purchase orders, supplier commitments and inbound supply.",inventory:"Inventory is shared operating state. Sales reduce stock, receiving increases it, transfers rebalance it, and low stock can trigger procurement.",receiving:"Receiving verifies quantity and condition against the shipment and PO before inventory is released.",expansion:"Store expansion follows 12 gates from market assessment through site, permits, build, readiness, go-live and hypercare.","it-portfolio":"IT portfolio delivery connects strategic outcomes to initiatives, delivery, releases, dependencies and value realization.",risks:"RAID management makes risks, issues, assumptions, dependencies and decisions visible, owned, dated and trackable.",shop:"The customer journey is browse → basket → checkout → shared inventory update → order confirmation."};
const fieldHelp={"Retail price":"Selling price for one unit. Used with unit cost to calculate the illustrative gross margin.","Unit cost":"Illustrative supplier cost per unit. Used with retail price for margin analysis.","On-hand units":"Current available quantity in the demo inventory record.","Par level":"Target stock position used to identify replenishment needs.","Lead time (days)":"Expected supplier lead time from order placement to availability.","Payment terms":"Illustrative commercial terms for supplier payment.","Approved budget":"Authorized investment envelope for the project or initiative.","Target opening":"Planned go-live date for the store.","Accountable owner":"Person or team responsible for moving the work forward.","Severity":"Business impact level used to prioritize a RAID item.","Due date":"Expected completion or mitigation date.","Priority":"Relative urgency of the work item.","Work area":"Business domain responsible for the task.","Fulfillment":"How the customer receives the order in this demo.","SKU / item":"Product identifier used to specify the inventory being transferred.","Units":"Quantity being moved between locations.","Reason":"Business reason for the inventory transfer."};
function tooltipFor(el){let raw=(el.getAttribute("placeholder")||el.textContent||"").replace(/\s+/g," ").trim();if(!raw)return "";if(fieldHelp[raw])return fieldHelp[raw];if(el.matches(".field label"))return "Input field: "+raw+". Enter the value needed for the current workflow.";if(el.matches("th"))return "Column definition: "+raw+". Use it to compare the records in this table.";if(el.matches(".kpi")){let x=el.querySelector(".kpi-label");return x?"Key operating measure: "+x.textContent.trim()+". Use the value and trend to identify attention.":""}if(el.matches(".status"))return "Status indicator: "+raw+". It summarizes the current state or exception level.";if(el.matches(".progress"))return "Progress indicator showing relative completion or health for the item.";if(el.matches(".stage"))return "Stage-gate item. Completed stages represent approved evidence; the current stage requires evidence and sign-off.";if(el.matches("button"))return "Action: "+raw+". This demonstrates the next operational step in the current workflow.";return "Field: "+raw+". This value supports the workflow shown on the current page.";}
function enhanceTooltips(){$$("input,select,textarea,button,th,.field label,.role-box label,.kpi,.status,.progress,.stage,.card-title,.metric-line,.journey-step").forEach(el=>{let t=tooltipFor(el);if(t){el.classList.add("has-tip");el.dataset.tip=t;}});}
function chatAnswer(q){let p=titles[S.page]?.[0]||"this page";let h=pageHelp[S.page]||titles[S.page]?.[1]||"This page supports the connected retail operating model.";q=q.toLowerCase().trim();if(/what is|what does|purpose|explain/.test(q))return p+": "+h;if(/flow|process|journey|end to end|how does/.test(q))return "Current flow: "+h+" The visible actions and statuses represent handoffs between accountable teams.";if(/next|what should|action|do i/.test(q))return "Next: review the highest-priority exception or current stage, then use the available action to move the workflow forward.";if(/field|column|metric|number|value/.test(q))return "Hover over the field or column you want to understand. Its tooltip explains what it means and how it is used.";if(/risk|issue|exception/.test(q))return "Start with critical or warning indicators. Confirm the owner, due date and mitigation, then verify the downstream business result.";if(/role|owner|responsib/.test(q))return "You are viewing this page as "+S.role+". The design shows the accountable owner and the handoff to the next operating team.";if(/inventory|stock|replenish/.test(q))return "Inventory is shared state: sales reduce stock, receiving increases it, transfers rebalance it, and low stock can create a procurement signal.";if(/product|sku/.test(q)&&S.page==="product-pipeline")return pageHelp["product-pipeline"];if(/store|opening|launch/.test(q)&&S.page==="expansion")return pageHelp.expansion;if(/po|purchase|buy/.test(q))return "Procurement converts demand signals into supplier commitments. A PO can lead to an inbound shipment, receiving, and released inventory.";return "I can explain this page, its fields, statuses, workflow, ownership, risks and recommended next action. Try “What is this page?”, “Explain the flow”, or “What happens next?”";}
function ensureChat(){let c=$("#contextChat");if(c){c.querySelector(".chat-context").textContent=(titles[S.page]?.[0]||"Operations")+" · "+S.role;return;}let x=document.createElement("div");x.id="contextChat";x.innerHTML='<button class="chat-launch" aria-label="Open page-aware help">?</button><div class="chat-panel"><div class="chat-head"><div><b>Sofia</b><small class="chat-context"></small></div><button class="chat-close">×</button></div><div class="chat-body"><div class="chat-msg assistant">I’m aware of the page and role you are viewing. Ask about a field, metric, status, workflow, owner or next step.</div></div><div class="chat-form"><input class="chat-input" autocomplete="off" placeholder="Ask about this page or flow…"><button class="chat-ask">Ask</button></div></div>';document.body.appendChild(x);x.querySelector(".chat-launch").onclick=()=>x.classList.toggle("open");x.querySelector(".chat-close").onclick=()=>x.classList.remove("open");x.querySelector(".chat-ask").onclick=()=>{let i=x.querySelector(".chat-input"),q=i.value.trim();if(!q)return;let b=x.querySelector(".chat-body"),u=document.createElement("div"),a=document.createElement("div");u.className="chat-msg user";u.textContent=q;a.className="chat-msg assistant";a.textContent=chatAnswer(q);b.append(u,a);b.scrollTop=b.scrollHeight;i.value="";};}function render(){if(S.role==='Customer'&&!['shop','my-orders','messages','work-queue'].includes(S.page))S.page='shop';if(S.role!=='Customer'&&['shop','my-orders'].includes(S.page))S.page='overview';let nav=groups.map(g=>{let a=g[1].filter(i=>vis().some(v=>v[0]===i[0]));return a.length?'<div class="nav-label">'+g[0]+'</div><div class="nav-list">'+a.map(i=>'<button class="nav-item '+(S.page===i[0]?'active':'')+'" data-page="'+i[0]+'"><span class="nav-icon">'+i[1]+'</span>'+i[2]+'</button>').join('')+'</div>':''}).join('');$('#app').innerHTML='<div class="app"><header class="topbar"><div class="brand"><button class="top-btn mobile-menu" data-action="menu">☰</button><div class="brand-mark">U</div><div>UOWE <small>MARKETOPS 360</small></div></div><div class="top-right"><span class="top-chip">● DEMO ENVIRONMENT</span><span class="top-chip">Nov 20, 2026</span><button class="top-btn" data-action="help">? Help</button><div class="user-dot">'+S.role.split(' ').map(x=>x[0]).join('').slice(0,2)+'</div></div></header><div class="frame"><aside class="sidebar" id="sidebar"><div class="role-box"><label>Experience as</label><select id="roleSelect">'+roles.map(r=>'<option '+(S.role===r?'selected':'')+'>'+r+'</option>').join('')+'</select></div>'+nav+'<div class="side-foot">CONNECTED RETAIL OPERATING MODEL<br>Illustrative demo data · Front-end prototype</div></aside><main class="main">'+(S.page==='shop'?shop():S.page==='my-orders'?myOrders():pageHead()+(renderers[S.page]||dashboard)())+'</main></div></div>';bind();enhanceTooltips();ensureChat()}
function notify(m){$('.toast')?.remove();let x=document.createElement('div');x.className='toast';x.textContent=m;document.body.appendChild(x);setTimeout(()=>x.remove(),2600)}
function bind(){let r=$('#roleSelect');if(r)r.onchange=()=>{S.role=r.value;S.page=r.value==='Customer'?'shop':(vis()[0]?.[0]||'overview');render()};$$('[data-page]').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;S.search='';S.filter='All';render();$('#sidebar')?.classList.remove('open')});let q=$('#search');if(q)q.oninput=()=>{S.search=q.value;let p=q.selectionStart,y=scrollY;render();let n=$('#search');if(n){n.focus();n.setSelectionRange(p,p)}scrollTo(0,y)};let f=$('#filter');if(f)f.onchange=()=>{S.filter=f.value;render()};$$('[data-filter]').forEach(b=>b.onclick=()=>{S.filter=b.dataset.filter;render()});$$('[data-add]').forEach(b=>b.onclick=()=>addCart(b.dataset.add));$$('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action))}
function addCart(sku){let p=S.products.find(x=>x.sku===sku);if(!p||p.stock<=0)return notify('This item is currently unavailable.');let c=S.cart.find(x=>x.sku===sku);c?c.qty++:S.cart.push({sku,qty:1});notify(p.name+' added to basket');render()}
function modal(title,body,submit,action){let x=document.createElement('div');x.className='modal-shade';x.innerHTML='<div class="modal"><div class="card-head"><h2>'+title+'</h2><button class="btn" data-close>✕</button></div>'+body+'<div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-save>'+submit+'</button></div></div>';document.body.appendChild(x);enhanceTooltips();x.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>x.remove());x.onclick=e=>{if(e.target===x)x.remove()};x.querySelector('[data-save]').onclick=()=>{let f=x.querySelector('form');if(f&&!f.reportValidity())return;let d=f?Object.fromEntries(new FormData(f)):{};const saved=commit(action,d);if(saved!==false)x.remove()}}
const demoDefaults={title:'Review low-stock replenishment',owner:'A. Rivera',due:'Nov 25, 2026',name:'Seasonal Citrus Selection',supplier:'Coastal Produce Partners',price:'4.99',cost:'2.35',stock:'24',par:'36',budget:'250000',open:'Mar 2027',city:'Pasadena, CA',lead:'5',sku:'PRD-1042',units:'12',reason:'Demand rebalance'};
const escAttr=v=>String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
const field=(l,n,p='',t='text')=>'<div class="field"><label>'+l+'</label><input name="'+n+'" type="'+t+'" placeholder="'+escAttr(p)+'" value="'+escAttr(demoDefaults[n]??(t==='number'?(p&&Number.isFinite(Number(p))?p:'0'):p))+'" required></div>';
const sel=(l,n,opts)=>'<div class="field"><label>'+l+'</label><select name="'+n+'">'+opts.map(x=>'<option>'+x+'</option>').join('')+'</select></div>';
function commit(a,d){if(a.startsWith('inventory-adjust:')){const sku=a.slice('inventory-adjust:'.length),p=S.products.find(x=>x.sku===sku),n=Number(d.verified);if(!p||!Number.isInteger(n)||n<0){notify('Invalid inventory adjustment');return}S.inventoryAdjustments=S.inventoryAdjustments||[];S.inventoryAdjustments.unshift({sku,product:p.name,before:p.stock,after:n,reason:d.reason,reference:d.reference,notes:d.notes,role:S.role});p.stock=n;notify(p.name+' inventory updated from '+S.inventoryAdjustments[0].before+' to '+n);render();return}if(a==='task'){S.tasks.unshift({id:'T-'+(220+S.tasks.length),title:d.title,area:d.area,owner:d.owner,due:d.due,status:'Open',priority:d.priority});notify('Task added to shared operations queue')}
if(a==='product'){S.products.unshift({sku:'NEW-'+(100+S.products.length),name:d.name,dept:d.dept,supplier:d.supplier,price:+d.price,cost:+d.cost,stock:+d.stock,par:+d.par,emoji:'🛍',status:'New item',margin:Math.round((1-d.cost/d.price)*100)});notify('New item added to product and inventory master')}
if(a==='risk'){S.risks.unshift({id:'R-'+(120+S.risks.length),title:d.title,area:d.area,owner:d.owner,severity:d.severity,due:d.due,status:'Open'});notify('RAID item logged')}
if(a==='expansion'){S.expansions.unshift({id:'EXP-2027-0'+(S.expansions.length+1),name:d.name,city:d.city,stage:1,budget:+d.budget,spent:0,forecast:+d.budget,owner:d.owner,open:d.open,health:'On track',completion:5});notify('Expansion project created at market assessment gate')}
if(a==='supplier'){S.suppliers.unshift({id:'SUP-0'+(70+S.suppliers.length),name:d.name,category:d.category,score:0,lead:+d.lead,terms:d.terms,status:'Review'});notify('Supplier profile created · onboarding review required')}
if(a==='initiative'){S.initiatives.unshift({id:'IT-00'+(5+S.initiatives.length),name:d.name,owner:d.owner,health:'Green',progress:0,spend:0,budget:+d.budget,phase:'Discovery'});notify('Initiative added to portfolio')}
if(a==='transfer'){S.transferLog=S.transferLog||[];S.transferLog.unshift({id:'TR-'+(2210+S.transferLog.length),from:d.from,to:d.to,sku:d.sku,units:+d.units,reason:d.reason,status:'Awaiting dispatch'});notify('Transfer request logged for '+d.units+' units');}
if(a==='checkout'){let total=0,lines=0;S.cart.forEach(c=>{let p=S.products.find(x=>x.sku===c.sku);if(p&&p.stock>=c.qty){p.stock-=c.qty;total+=p.price*c.qty;lines+=c.qty}});if(!lines){notify('No available items in basket');return}S.orders.unshift({id:'ORD-'+(7100+S.orders.length),date:'Nov 20, 2026',lines,total,fulfillment:d.fulfillment||'Pickup · Westside',status:'Confirmed'});S.cart=[];notify('Order placed. Shared store inventory updated.')}render()}
function act(a){if(a==='menu')return $('#sidebar')?.classList.toggle('open');if(a==='go-expansion'){S.page='expansion';render();return}if(a==='go-risks'){S.page='risks';render();return}if(a==='go-stores'){S.page='stores';render();return}if(a==='go-inventory'){S.page='inventory';render();return}if(a==='go-procurement'){S.page='procurement';render();return}if(a==='go-shop'){S.role='Customer';S.page='shop';render();return}if(a==='browse'){document.querySelector('.dept-pills')?.scrollIntoView({behavior:'smooth'});return}
if(a==='help')return modal('MarketOps 360 · Demo guide','<p>Switch roles to explore responsibilities. Actions update shared demo data: customer checkout changes stock; receiving releases stock; buying and distribution connect replenishment to inventory; expansion gates and RAID connect to IT portfolio governance.</p><p>This is a front-end-only prototype with illustrative data and simulated actions.</p>','Got it','noop');
if(a==='cart'){let total=S.cart.reduce((sum,c)=>sum+S.products.find(p=>p.sku===c.sku).price*c.qty,0);return modal('Your basket',S.cart.length?S.cart.map(c=>{let p=S.products.find(x=>x.sku===c.sku);return '<div class="list-row"><div class="list-icon">'+p.emoji+'</div><div class="list-main"><strong>'+p.name+'</strong><p>'+c.qty+' × '+money(p.price)+'</p></div><b>'+money(p.price*c.qty)+'</b></div>'}).join('')+'<div class="metric-line"><b>Subtotal</b><b>'+money(total)+'</b></div><form>'+sel('Fulfillment','fulfillment',['Pickup · Westside','Pickup · North Park','Pickup · Downtown'])+'</form>':'<div class="empty">Your basket is empty.</div>','Place demo order','checkout')}
if(a==='new-task')return modal('Create operating task','<form>'+field('Task title','title','Describe the work')+sel('Work area','area',['Store operations','Procurement','Distribution','Expansion','Quality','Technology'])+field('Owner','owner','Team or accountable person')+field('Due','due','Today · 4:00 PM')+sel('Priority','priority',['High','Medium','Low'])+'</form>','Add task','task');
if(a==='new-product')return modal('Create product / SKU','<form>'+field('Product name','name','Item name')+sel('Department','dept',['Produce','Dairy & Alternatives','Pantry','Frozen','Bakery','Snacks','Beverages','Meat & Seafood'])+field('Supplier','supplier','Supplier name')+'<div class="modal-grid">'+field('Retail price','price','0.00','number')+field('Unit cost','cost','0.00','number')+field('On-hand units','stock','0','number')+field('Par level','par','12','number')+'</div></form>','Create item','product');
if(a==='new-risk')return modal('Log risk / issue / dependency','<form>'+field('Title','title','Describe the risk or issue')+sel('Area','area',['Site & lease','Permits & legal','Construction','Technology','Supply readiness','Workforce','Store operations','Quality'])+field('Owner','owner','Accountable owner')+sel('Severity','severity',['Critical','High','Medium','Low'])+field('Due date','due','Nov 25')+'</form>','Log item','risk');
if(a==='new-expansion')return modal('Create expansion project','<form>'+field('Project / store name','name','New market name')+field('City','city','City, State')+'<div class="modal-grid">'+field('Approved budget','budget','2500000','number')+field('Target opening','open','Mar 2027')+'</div>'+field('Accountable owner','owner','Expansion lead')+'</form>','Create project','expansion');
if(a==='new-supplier')return modal('Onboard supplier','<form>'+field('Supplier name','name','Legal supplier name')+sel('Category','category',['Produce','Pantry','Dairy alternatives','Frozen','Bakery','Meat & seafood','Beverages'])+'<div class="modal-grid">'+field('Lead time (days)','lead','5','number')+sel('Payment terms','terms',['Net 7','Net 15','Net 30','Net 45'])+'</div></form>','Start onboarding','supplier');
if(a==='new-initiative')return modal('Create portfolio initiative','<form>'+field('Initiative name','name','Business outcome')+field('Business owner','owner','Accountable owner')+field('Approved budget','budget','250000','number')+'</form>','Add initiative','initiative');
if(a==='advance-product'){let p=S.pipeline[0];if(p.stage<12)p.stage++;let item=S.products.find(x=>x.name===p.name);if(item&&p.stage>=10){item.stock=Math.max(item.stock,item.par);item.status='Active'}notify('Product gate advanced to '+p.stage+' · '+S.productStages[p.stage-1]);render();return}
if(a==='receive-shipment'){let s=S.shipments.find(x=>x.status!=='Received');if(!s)return notify('All listed shipments are received');s.status='Received';s.eta='Received · just now';let p=S.products.find(x=>x.supplier===s.supplier&&x.stock<x.par)||S.products.find(x=>x.supplier===s.supplier);if(p)p.stock+=Math.max(1,Math.round(s.cases/8));let po=S.pos.find(x=>x.id===s.po);if(po)po.status='Received';notify(s.id+' received; supplier-linked inventory released');render();return}
if(a==='create-po'){let p=S.products.find(x=>x.stock<x.par);if(p){let id='PO-'+(48300+S.pos.length),qty=Math.max(p.par*2-p.stock,1);S.pos.unshift({id,supplier:p.supplier,date:'Nov 20',amount:Math.round(qty*p.cost),status:'Draft',lines:1});S.shipments.unshift({id:'ASN-'+(7310+S.shipments.length),po:id,supplier:p.supplier,dc:'DC West',eta:'Tomorrow · 8:00 AM',cases:qty,status:'Scheduled'});notify('Draft PO and inbound appointment created for '+p.supplier);render()}return}
if(a==='resolve-risk'){let r=S.risks.find(x=>x.status!=='Closed');if(r){r.status='Closed';notify(r.id+' closed in RAID register');render()}return}
if(a.startsWith('adjust-stock')){const sku=a.split(':')[1];const p=S.products.find(x=>x.sku===sku);if(!p)return notify('Inventory item not found');const body='<form><div class="field"><label>Product / SKU</label><input value="'+escAttr(p.name+' · '+p.sku)+'" disabled></div><div class="modal-grid"><div class="field"><label>Current on-hand</label><input value="'+p.stock+'" disabled></div><div class="field"><label>Verified on-hand</label><input name="verified" type="number" min="0" step="1" value="'+p.stock+'" required></div></div><div class="field"><label>Reason</label><select name="reason"><option>Cycle count correction</option><option>Damage / shrink</option><option>Receiving discrepancy</option><option>Other correction</option></select></div><div class="field"><label>Reference</label><input name="reference" value="COUNT-2026-001" required></div><div class="field"><label>Notes</label><input name="notes" value="Verified against physical shelf count" required></div><p class="card-sub">Example values are editable. Saving updates the selected SKU and related inventory metrics.</p></form>';return modal('Adjust inventory · '+p.sku,body,'Save adjustment','inventory-adjust:'+p.sku)}
if(a==='advance-expansion'){let x=S.expansions[0];if(x.stage<12){x.stage++;x.completion=Math.min(100,Math.round(x.stage/12*100));if(x.stage===12){x.health='Stabilizing';if(!S.stores.some(s=>s.name===x.name))S.stores.push({id:'ST-'+(105+S.stores.length),name:x.name,city:x.city,region:'West',sales:0,traffic:0,health:'Pre-opening',manager:'Opening team'});}notify(x.name+' advanced to gate '+x.stage+' · '+S.stages[x.stage-1]);}else notify('All expansion stage gates are complete');render();return}
if(a==='new-transfer')return modal('Create store transfer','<form>'+sel('From store','from',['Westside','North Park','Downtown'])+sel('To store','to',['Downtown','Westside','North Park'])+field('SKU / item','sku','Item or SKU')+field('Units','units','12','number')+field('Reason','reason','Demand rebalance')+'</form>','Create transfer','transfer');
if(a==='transfer-action'){let x=(S.transferLog||[]).find(t=>t.status!=='Completed');if(x){x.status=x.status==='Awaiting dispatch'?'In transit':'Completed';notify(x.id+' status updated to '+x.status);render();return}return notify('Seed transfer status updated in this demo view')}
if(a==='governance'||a==='noop')return notify('Demo action acknowledged');notify('Demo interaction selected: '+a.replaceAll('-',' '))}
document.addEventListener('DOMContentLoaded',()=>render());

